#!/usr/bin/env node
/**
 * CLI for the Eliza API client
 *
 * Usage:
 *   eliza-cli quota
 *   eliza-cli usage
 *   eliza-cli balance
 *   eliza-cli delete-daily-quota
 *   eliza-cli balance --pool my_team_pool
 *   eliza-cli pools get my_team_pool
 *   eliza-cli pools set my_team_pool --abc my_abc --member robot-my --member abc:my_abc/development
 *   eliza-cli pools delete my_team_pool
 *   eliza-cli models list
 *   eliza-cli models resolve claude-sonnet-4-5
 *   eliza-cli models search minimax
 */
import { Command } from "commander";
import createLogger from "@yandex-int/yandex-logger";
import { printNestedErrorCause } from "./cli-error-utils.js";
import { ElizaApiError, ElizaClient, ElizaNetworkError, ElizaTimeoutError, ModelNotFoundError, ModelResolver, NoAvailableTokensError, UnsupportedVendorError, } from "./index.js";
import { resolveElizaToken } from "./token.js";
const logger = createLogger({ name: "eliza-cli" });
function logNestedErrorCause(error) {
    printNestedErrorCause(error, (line) => logger.error(line));
}
// ============================================================================
// Token resolver
// ============================================================================
function getToken() {
    return resolveElizaToken();
}
// ============================================================================
// Formatting helpers
// ============================================================================
function formatRemaining(value) {
    if (value === null)
        return "unlimited";
    return value.toFixed(4);
}
function formatCost(value) {
    if (value === -1)
        return "unlimited";
    return value.toFixed(4);
}
function collectMember(value, previous) {
    previous.push(value);
    return previous;
}
// ============================================================================
// Command handlers
// ============================================================================
async function runQuota(token, pool, json) {
    const client = new ElizaClient();
    const response = await client.getQuota(token, pool);
    if (json) {
        console.log(JSON.stringify(response, null, 2));
        return;
    }
    const quota = response.quota;
    if (response.login)
        console.log(`Login:   ${response.login}`);
    if (response.pool)
        console.log(`Pool:    ${response.pool}`);
    if (response.account)
        console.log(`Account: ${response.account}`);
    console.log("");
    console.log("Quota limits:");
    console.log(`  Daily   cost limit:    ${formatCost(quota.all.daily.cost)}`);
    console.log(`  Daily   request limit: ${quota.all.daily.requests === -1
        ? "unlimited"
        : quota.all.daily.requests}`);
    console.log(`  Monthly cost limit:    ${formatCost(quota.all.monthly.cost)}`);
    console.log(`  Monthly request limit: ${quota.all.monthly.requests === -1
        ? "unlimited"
        : quota.all.monthly.requests}`);
    const modelKeys = Object.keys(quota).filter((k) => k !== "all");
    if (modelKeys.length > 0) {
        console.log("\nPer-model quotas:");
        for (const modelKey of modelKeys) {
            const m = quota[modelKey];
            console.log(`  [${modelKey}]`);
            console.log(`    Daily:   cost=${formatCost(m.daily.cost)}, requests=${m.daily.requests}`);
            console.log(`    Monthly: cost=${formatCost(m.monthly.cost)}, requests=${m.monthly.requests}`);
        }
    }
}
async function runUsage(token, pool, json) {
    const client = new ElizaClient();
    const response = await client.getUsage(token, pool);
    if (json) {
        console.log(JSON.stringify(response, null, 2));
        return;
    }
    const usage = response.usage;
    if (response.login)
        console.log(`Login:   ${response.login}`);
    if (response.pool)
        console.log(`Pool:    ${response.pool}`);
    if (response.account)
        console.log(`Account: ${response.account}`);
    console.log("");
    console.log("Usage so far:");
    console.log(`  Daily   cost:     ${usage.all.daily.cost.toFixed(4)}`);
    console.log(`  Daily   requests: ${usage.all.daily.requests}`);
    console.log(`  Monthly cost:     ${usage.all.monthly.cost.toFixed(4)}`);
    console.log(`  Monthly requests: ${usage.all.monthly.requests}`);
    const modelKeys = Object.keys(usage).filter((k) => k !== "all");
    if (modelKeys.length > 0) {
        console.log("\nPer-model usage:");
        for (const modelKey of modelKeys) {
            const m = usage[modelKey];
            console.log(`  [${modelKey}]`);
            console.log(`    Daily:   cost=${m.daily.cost.toFixed(4)}, requests=${m.daily.requests}`);
            console.log(`    Monthly: cost=${m.monthly.cost.toFixed(4)}, requests=${m.monthly.requests}`);
        }
    }
}
async function runBalance(token, pool, json) {
    const client = new ElizaClient();
    const balance = await client.getBalance(token, "cli-token", pool);
    if (json) {
        console.log(JSON.stringify(balance, null, 2));
        return;
    }
    if (pool)
        console.log(`Pool:              ${pool}`);
    console.log("");
    console.log("Remaining balance:");
    console.log(`  Daily remaining:   ${formatRemaining(balance.dailyRemaining)}`);
    console.log(`  Monthly remaining: ${formatRemaining(balance.monthlyRemaining)}`);
    console.log(`  Effective balance: ${balance.effectiveBalance === Infinity
        ? "unlimited"
        : balance.effectiveBalance.toFixed(4)}`);
}
async function runDeleteDailyQuota(token, pool, json) {
    const client = new ElizaClient();
    await client.deleteDailyQuota(token, pool);
    if (json) {
        console.log(JSON.stringify({
            ok: true,
            action: "delete-daily-quota",
            ...(pool ? { pool } : {}),
        }, null, 2));
        return;
    }
    if (pool) {
        console.log(`Pool: ${pool}`);
    }
    console.log("Daily quota deleted.");
}
async function runPoolGet(token, poolId, json) {
    const client = new ElizaClient();
    const response = await client.getPool(token, poolId);
    if (json) {
        console.log(JSON.stringify(response, null, 2));
        return;
    }
    console.log(`Pool: ${poolId}`);
    console.log(JSON.stringify(response, null, 2));
}
async function runPoolSet(token, poolId, abc, members, json) {
    const client = new ElizaClient();
    const response = await client.setPool(token, poolId, { abc, members });
    if (json) {
        console.log(JSON.stringify(response, null, 2));
        return;
    }
    console.log(response.status || `Updated pool ${poolId}`);
    if (response.logins?.length) {
        console.log(`Logins: ${response.logins.join(", ")}`);
    }
}
async function runPoolDelete(token, poolId, json) {
    const client = new ElizaClient();
    await client.deletePool(token, poolId);
    if (json) {
        console.log(JSON.stringify({
            ok: true,
            action: "delete-pool",
            pool: poolId,
        }, null, 2));
        return;
    }
    console.log(`Pool deleted: ${poolId}`);
}
async function runModelsList(token, json) {
    const resolver = new ModelResolver({ token });
    const models = await resolver.getModels();
    if (json) {
        console.log(JSON.stringify(models, null, 2));
        return;
    }
    console.log(`Available models (${models.length} total):\n`);
    // Pad columns for tabular output
    const idWidth = Math.min(50, Math.max(10, ...models.map((m) => m.id.length)));
    const vendorWidth = Math.max(8, ...models.map((m) => m.vendor.length));
    const header = `${"ID".padEnd(idWidth)}  ${"VENDOR".padEnd(vendorWidth)}  TITLE`;
    console.log(header);
    console.log("-".repeat(header.length + 10));
    for (const m of models) {
        const id = m.id.padEnd(idWidth);
        const vendor = m.vendor.padEnd(vendorWidth);
        const title = m.title ?? "";
        console.log(`${id}  ${vendor}  ${title}`);
    }
}
async function runModelsResolve(token, modelId, json) {
    const resolver = new ModelResolver({ token });
    const resolved = await resolver.resolve(modelId);
    if (json) {
        console.log(JSON.stringify(resolved, null, 2));
        return;
    }
    console.log(`Model:    ${resolved.modelId}`);
    console.log(`Vendor:   ${resolved.vendor}`);
    console.log(`Endpoint: ${resolved.endpoint}`);
    console.log(`Base URL: ${resolved.baseUrl}`);
    console.log(`Full URL: ${resolved.baseUrl}${resolved.endpoint}`);
}
async function runModelsSearch(token, query, json) {
    const resolver = new ModelResolver({ token });
    const results = await resolver.searchModels(query);
    if (json) {
        console.log(JSON.stringify(results, null, 2));
        return;
    }
    if (results.length === 0) {
        console.log(`No models found matching "${query}"`);
        return;
    }
    console.log(`Found ${results.length} model(s) matching "${query}":\n`);
    const idWidth = Math.min(50, Math.max(10, ...results.map((m) => m.id.length)));
    const vendorWidth = Math.max(8, ...results.map((m) => m.vendor.length));
    const header = `${"ID".padEnd(idWidth)}  ${"VENDOR".padEnd(vendorWidth)}  TITLE`;
    console.log(header);
    console.log("-".repeat(header.length + 10));
    for (const m of results) {
        const id = m.id.padEnd(idWidth);
        const vendor = m.vendor.padEnd(vendorWidth);
        const title = m.title ?? "";
        console.log(`${id}  ${vendor}  ${title}`);
    }
}
// ============================================================================
// Main
// ============================================================================
const program = new Command();
program
    .name("eliza-cli")
    .description("Eliza API Client CLI")
    .option("--pool <name>", "Pool name for Ya-Pool header")
    .option("--json", "Output raw JSON", false);
program
    .command("quota")
    .description("Get quota limits for token")
    .action(async () => {
    const opts = program.opts();
    const token = getToken();
    await runQuota(token, opts.pool, opts.json);
});
program
    .command("usage")
    .description("Get current usage for token")
    .action(async () => {
    const opts = program.opts();
    const token = getToken();
    await runUsage(token, opts.pool, opts.json);
});
program
    .command("balance")
    .description("Get remaining balance (quota - usage)")
    .action(async () => {
    const opts = program.opts();
    const token = getToken();
    await runBalance(token, opts.pool, opts.json);
});
program
    .command("delete-daily-quota")
    .description("Delete daily quota for token")
    .action(async () => {
    const opts = program.opts();
    const token = getToken();
    await runDeleteDailyQuota(token, opts.pool, opts.json);
});
const pools = program.command("pools").description("Pool operations");
pools
    .command("get")
    .argument("<poolId>", "Pool ID to inspect")
    .description("Get pool information")
    .action(async (poolId) => {
    const opts = program.opts();
    const token = getToken();
    await runPoolGet(token, poolId, opts.json);
});
pools
    .command("set")
    .argument("<poolId>", "Pool ID to create or update")
    .requiredOption("--abc <slug>", "ABC service slug for cost attribution")
    .option("--member <member>", "Pool member; repeat for multiple members (login, abc:slug[/scope], tvm:id)", collectMember, [])
    .description("Create or update a pool with a full member list")
    .action(async (poolId, opts) => {
    if (opts.member.length === 0) {
        throw new Error("At least one --member is required");
    }
    const globalOpts = program.opts();
    const token = getToken();
    await runPoolSet(token, poolId, opts.abc, opts.member, globalOpts.json);
});
pools
    .command("delete")
    .argument("<poolId>", "Pool ID to delete")
    .description("Delete a pool")
    .action(async (poolId) => {
    const opts = program.opts();
    const token = getToken();
    await runPoolDelete(token, poolId, opts.json);
});
const models = program.command("models").description("Model operations");
models
    .command("list")
    .description("List all available models")
    .action(async () => {
    const opts = program.opts();
    const token = getToken();
    await runModelsList(token, opts.json);
});
models
    .command("resolve")
    .argument("<modelId>", "Model ID to resolve")
    .description("Resolve model to vendor + endpoint")
    .action(async (modelId) => {
    const opts = program.opts();
    const token = getToken();
    await runModelsResolve(token, modelId, opts.json);
});
models
    .command("search")
    .argument("<query>", "Search query")
    .description("Search models by partial ID match")
    .action(async (query) => {
    const opts = program.opts();
    const token = getToken();
    await runModelsSearch(token, query, opts.json);
});
program.parseAsync().catch((error) => {
    if (error instanceof ElizaApiError) {
        logger.error(`API error (HTTP ${error.statusCode}): ${error.message}`);
        if (error.responseBody) {
            logger.error(`Response: ${error.responseBody}`);
        }
        logNestedErrorCause(error);
    }
    else if (error instanceof ElizaTimeoutError) {
        logger.error(`Timeout: ${error.message}`);
        logNestedErrorCause(error);
    }
    else if (error instanceof ElizaNetworkError) {
        logger.error(`Network error: ${error.message}`);
        logNestedErrorCause(error);
    }
    else if (error instanceof NoAvailableTokensError) {
        logger.error(`No available tokens: ${error.message}`);
    }
    else if (error instanceof ModelNotFoundError) {
        logger.error(`Model not found: ${error.modelId}`);
        if (error.availableModels?.length) {
            logger.error("Some available models:");
            for (const m of error.availableModels.slice(0, 10)) {
                logger.error(`  - ${m}`);
            }
        }
    }
    else if (error instanceof UnsupportedVendorError) {
        logger.error(`Unsupported vendor: ${error.vendor} for model ${error.modelId}`);
    }
    else {
        logger.error(`Fatal error: ${error instanceof Error ? error.message : String(error)}`);
        logNestedErrorCause(error);
    }
    process.exit(1);
});
